import{bV as a,aL as s,u as n,G as e}from"./chunks/framework.BgjPrbJw.js";const k=JSON.parse('{"title":"Git","description":"Git 常用命令与工作流备忘：分支、提交与协作。","frontmatter":{"title":"Git","date":"2021-06-01T00:00:00.000Z","categories":["版本控制工具"],"tags":["Git"],"description":"Git 常用命令与工作流备忘：分支、提交与协作。","coverImg":"/images/cover-5.svg","permalink":"/posts/git"},"headers":[],"relativePath":"posts/git.md","filePath":"posts/git.md","lastUpdated":1795509423000}'),l={name:"posts/git.md"};function t(p,i,r,h,g,d){return s(),n("div",null,[...i[0]||(i[0]=[e(`<h1 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h1><h2 id="_1-版本控制" tabindex="-1">1.版本控制 <a class="header-anchor" href="#_1-版本控制" aria-label="Permalink to &quot;1.版本控制&quot;">​</a></h2><h3 id="常见的版本控制工具" tabindex="-1">常见的版本控制工具 <a class="header-anchor" href="#常见的版本控制工具" aria-label="Permalink to &quot;常见的版本控制工具&quot;">​</a></h3><ul><li><strong>Git</strong></li><li><strong>SVN</strong></li><li><strong>CVS</strong></li><li><strong>VSS</strong></li><li><strong>TFS</strong></li><li>Visul Studio Online</li></ul><h3 id="版本控制分类" tabindex="-1">版本控制分类 <a class="header-anchor" href="#版本控制分类" aria-label="Permalink to &quot;版本控制分类&quot;">​</a></h3><h4 id="本地版本控制" tabindex="-1">本地版本控制 <a class="header-anchor" href="#本地版本控制" aria-label="Permalink to &quot;本地版本控制&quot;">​</a></h4><blockquote><p>其中最流行的一种叫做 RCS，现今许多计算机系统上都还看得到它的踪影。甚至在流行的 Mac OS X 系统上安装了开发者工具包之后，也可以使用 rcs 命令。它的工作原理是在硬盘上保存补丁集（补丁是指文件修订前后的变化）；通过应用所有的补丁，可以重新计算出各个版本的文件内容。</p><p>缺点:开发者不能在不同系统的上协同工作</p></blockquote><p><img src="https://fanaidi.gitee.io/blogimgs/git/%E6%9C%AC%E5%9C%B0%E7%89%88%E6%9C%AC%E6%8E%A7%E5%88%B6.png" alt="" loading="lazy"></p><h4 id="集中式版本控制" tabindex="-1">集中式版本控制 <a class="header-anchor" href="#集中式版本控制" aria-label="Permalink to &quot;集中式版本控制&quot;">​</a></h4><blockquote><p>集中化的版本控制系统（Centralized Version Control Systems，简称 CVCS）.这类系统，诸如SVN、 CVS、Subversion 以及 Perforce 等，都有一个单一的集中管理的服务器，保存所有文件的修订版本，而协同工作的人们都通过客户端连到这台服务器，取出最新的文件或者提交更新。多年以来，这已成为版本控制系统的标准做法。</p><p>缺点:如果宕机一小时，那么在这一小时内，谁都无法提交更新，也就无法协同工作。如果中心数据库所在的磁盘发生损坏，又没有做恰当备份，毫无疑问你将丢失所有数据——包括项目的整个变更历史，只剩下人们在各自机器上保留的单独快照。本地版本控制系统也存在类似问题，只要整个项目的历史记录被保存在单一位置，就有丢失所有历史更新记录的风险。</p></blockquote><p><img src="https://fanaidi.gitee.io/blogimgs/git/%E5%88%86%E5%B8%83%E5%BC%8F%E7%89%88%E6%9C%AC%E6%8E%A7%E5%88%B6.png" alt="" loading="lazy"></p><h4 id="分布式版本控制" tabindex="-1">分布式版本控制 <a class="header-anchor" href="#分布式版本控制" aria-label="Permalink to &quot;分布式版本控制&quot;">​</a></h4><blockquote><p>分布式版本控制系统（Distributed Version Control System，简称 DVCS）.在这类系统中，像 Git、Mercurial、Bazaar 以及 Darcs 等，客户端并不只提取最新版本的文件快照，而是把代码仓库完整地镜像下来。这么一来，任何一处协同工作用的服务器发生故障，事后都可以用任何一个镜像出来的本地仓库恢复。因为每一次的克隆操作，实际上都是一次对代码仓库的完整备份。</p></blockquote><p><img src="https://fanaidi.gitee.io/blogimgs/git/%E9%9B%86%E4%B8%AD%E7%89%88%E6%9C%AC%E6%8E%A7%E5%88%B6.png" alt="" loading="lazy"></p><h3 id="git与svn最主要区别" tabindex="-1">Git与SVN最主要区别 <a class="header-anchor" href="#git与svn最主要区别" aria-label="Permalink to &quot;Git与SVN最主要区别&quot;">​</a></h3><blockquote><p>​ SVN是集中式版本控制系统，版本库是集中放在中央服务器的，而工作的时候，用的都是自己的电脑，所以首先要从中央服务器得到最新的版本，然后工作，完成工作后，需要把自己做完的活推送到中央服务器。集中式版本控制系统是必须联网才能工作，对网络带宽要求较高。</p><p>​ Git是分布式版本控制系统，没有中央服务器，每个人的电脑就是一个完整的版本库，工作的时候不需要联网，因为版本都在自己的电脑上。协同的方法是这样的：比如说自己在电脑上改了文件A，其他人也在电脑上改了文件A，这时，你们两之间只需把各自修改推送给对方，就可以互相看到对方的修改了。Git可以直接看到更新了哪些代码和文件！</p><p>​ Git是目前世界上最先进的分布式版本控制系统</p></blockquote><h2 id="git环境配置" tabindex="-1">Git环境配置 <a class="header-anchor" href="#git环境配置" aria-label="Permalink to &quot;Git环境配置&quot;">​</a></h2><h3 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h3><p>可以使用淘宝镜像快速下载：<a href="http://npm.taobao.org/mirrors/git-for-windows/" target="_blank" rel="noreferrer">http://npm.taobao.org/mirrors/git-for-windows/</a></p><p>安装：一直点下一步即可。</p><h3 id="启动git" tabindex="-1">启动Git <a class="header-anchor" href="#启动git" aria-label="Permalink to &quot;启动Git&quot;">​</a></h3><p>安装成功后在开始菜单中会有Git项，菜单下有3个程序：任意文件夹下右键也可以看到对应的程序！</p><ul><li>**Git Bash：**Unix与Linux风格的命令行，使用最多，推荐最多</li><li>**Git CMD：**Windows风格的命令行</li><li><strong>Git GUI</strong>：图形界面的Git，不建议初学者使用，尽量先熟悉常用命令</li></ul><h3 id="git配置" tabindex="-1">Git配置 <a class="header-anchor" href="#git配置" aria-label="Permalink to &quot;Git配置&quot;">​</a></h3><p>所有的配置文件，其实都保存在本地！</p><p><strong>查看配置</strong></p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>查看系统config</strong></p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --system</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>查看当前用户（global）配置</strong></p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --list</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Git相关的配置文件</strong></p><ol><li>Git\\etc\\gitconfig ：Git 安装目录下的 gitconfig --system 系统级</li><li>C:\\Users\\Administrator\\ .gitconfig 只适用于当前登录用户的配置 --global 全局</li></ol><p><img src="https://fanaidi.gitee.io/blogimgs/git/.gitconfig.png" alt="" loading="lazy"></p><p>这里可以直接编辑配置文件，通过命令设置后会响应到这里。</p><p><strong>==设置用户名与邮箱（用户标识，必要）==</strong></p><p>当你安装Git后首先要做的事情是设置你的用户名称和e-mail地址。这是非常重要的，因为每次Git提交都会使用该信息。它被永远的嵌入到了你的提交中：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;kuangshen&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  #名称</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 24736743@qq.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   #邮箱</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>只需要做一次这个设置，如果你传递了--global 选项，因为Git将总是会使用该信息来处理你在系统中所做的一切操作。如果你希望在一个特定的项目中使用不同的名称或e-mail地址，你可以在该项目中运行该命令而不要--global选项。总之--global为全局配置，不加为某个项目的特定配置。</p><h2 id="git基本理论-核心" tabindex="-1">Git基本理论（核心） <a class="header-anchor" href="#git基本理论-核心" aria-label="Permalink to &quot;Git基本理论（核心）&quot;">​</a></h2><h3 id="三个区域" tabindex="-1">三个区域 <a class="header-anchor" href="#三个区域" aria-label="Permalink to &quot;三个区域&quot;">​</a></h3><p>Git本地有三个工作区域：工作目录（Working Directory）、暂存区(Stage/Index)、资源库(Repository或Git Directory)。如果在加上远程的git仓库(Remote Directory)就可以分为四个工作区域。文件在这四个区域之间的转换关系如下：</p><p><img src="https://fanaidi.gitee.io/blogimgs/git/git%E4%B8%89%E4%B8%AA%E5%8C%BA%E5%9F%9F.png" alt="" loading="lazy"></p><ul><li>Workspace：工作区，就是你平时存放项目代码的地方</li><li>Index / Stage：暂存区，用于临时存放你的改动，事实上它只是一个文件，保存即将提交到文件列表信息</li><li>Repository：仓库区（或本地仓库），就是安全存放数据的位置，这里面有你提交到所有版本的数据。其中HEAD指向最新放入仓库的版本</li><li>Remote：远程仓库，托管代码的服务器，可以简单的认为是你项目组中的一台电脑用于远程数据交换</li></ul><p>本地的三个区域确切的说应该是git仓库中HEAD指向的版本：</p><p><img src="https://fanaidi.gitee.io/blogimgs/git/git%E6%A0%B8%E5%BF%83.png" alt="" loading="lazy"></p><ul><li>Directory：使用Git管理的一个目录，也就是一个仓库，包含我们的工作空间和Git的管理空间。</li><li>WorkSpace：需要通过Git进行版本控制的目录和文件，这些目录和文件组成了工作空间。</li><li>.git：存放Git管理信息的目录，初始化仓库的时候自动创建。</li><li>Index/Stage：暂存区，或者叫待提交更新区，在提交进入repo之前，我们可以把所有的更新放在暂存区。</li><li>Local Repo：本地仓库，一个存放在本地的版本库；HEAD会只是当前的开发分支（branch）。</li><li>Stash：隐藏，是一个工作状态保存栈，用于保存/恢复WorkSpace中的临时状态。</li></ul><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h3><p>git的工作流程一般是这样的：</p><ol><li>在工作目录中添加、修改文件；</li><li>将需要进行版本管理的文件放入暂存区域；</li><li>将暂存区域的文件提交到git仓库。</li></ol><p>因此，git管理的文件有三种状态：已修改（modified）,已暂存（staged）,已提交(committed)</p><p><img src="https://fanaidi.gitee.io/blogimgs/git/git.png" alt="" loading="lazy"></p><h3 id="git项目搭建" tabindex="-1">Git项目搭建 <a class="header-anchor" href="#git项目搭建" aria-label="Permalink to &quot;Git项目搭建&quot;">​</a></h3><h4 id="创建工作目录与常用指令" tabindex="-1">创建工作目录与常用指令 <a class="header-anchor" href="#创建工作目录与常用指令" aria-label="Permalink to &quot;创建工作目录与常用指令&quot;">​</a></h4><p>工作目录（WorkSpace)一般就是你希望Git帮助你管理的文件夹，可以是你项目的目录，也可以是一个空目录，建议不要有中文。</p><p>日常使用只要记住下图6个命令：</p><p><img src="https://fanaidi.gitee.io/blogimgs/git/git%E5%B8%B8%E7%94%A86%E4%B8%AA%E5%91%BD%E4%BB%A4.png" alt="" loading="lazy"></p><h4 id="本地仓库搭建" tabindex="-1">本地仓库搭建 <a class="header-anchor" href="#本地仓库搭建" aria-label="Permalink to &quot;本地仓库搭建&quot;">​</a></h4><p>创建本地仓库的方法有两种：一种是创建全新的仓库，另一种是克隆远程仓库。</p><ol><li><p>创建全新的仓库，需要用GIT管理的项目的根目录执行：</p><div class="language-Shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">Shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在当前目录新建一个Git代码库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>执行后可以看到，仅仅在项目目录多出了一个.git目录，关于版本等的所有信息都在这个目录里面。</p></li></ol><h4 id="克隆远程仓库" tabindex="-1">克隆远程仓库 <a class="header-anchor" href="#克隆远程仓库" aria-label="Permalink to &quot;克隆远程仓库&quot;">​</a></h4><ol><li><p>另一种方式是克隆远程目录，是将远程服务器上的仓库完全镜像一份至本地！</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆一个项目和它的整个代码历史(版本信息)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [url]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li></ol><h3 id="git文件操作" tabindex="-1">Git文件操作 <a class="header-anchor" href="#git文件操作" aria-label="Permalink to &quot;Git文件操作&quot;">​</a></h3><h4 id="文件的四种状态" tabindex="-1">文件的四种状态 <a class="header-anchor" href="#文件的四种状态" aria-label="Permalink to &quot;文件的四种状态&quot;">​</a></h4><p>版本控制就是对文件的版本控制，要对文件进行修改、提交等操作，首先要知道文件当前在什么状态，不然可能会提交了现在还不想提交的文件，或者要提交的文件没提交上。</p><ul><li>Untracked: 未跟踪, 此文件在文件夹中, 但并没有加入到git库, 不参与版本控制. 通过git add 状态变为Staged.</li><li>Unmodify: 文件已经入库, 未修改, 即版本库中的文件快照内容与文件夹中完全一致. 这种类型的文件有两种去处, 如果它被修改, 而变为Modified. 如果使用git rm移出版本库, 则成为Untracked文件</li><li>Modified: 文件已修改, 仅仅是修改, 并没有进行其他的操作. 这个文件也有两个去处, 通过git add可进入暂存staged状态, 使用git checkout 则丢弃修改过, 返回到unmodify状态, 这个git checkout即从库中取出文件, 覆盖当前修改 !</li><li>Staged: 暂存状态. 执行git commit则将修改同步到库中, 这时库中的文件和本地文件又变为一致, 文件为Unmodify状态. 执行git reset HEAD filename取消暂存, 文件状态为Modified</li></ul><h4 id="查看文件状态" tabindex="-1">查看文件状态 <a class="header-anchor" href="#查看文件状态" aria-label="Permalink to &quot;查看文件状态&quot;">​</a></h4><p>上面说文件有4种状态，通过如下命令可以查看到文件的状态：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#查看指定文件状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [filename]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#查看所有文件状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># git add .                  添加所有文件到暂存区</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># git commit -m &quot;消息内容&quot;    提交暂存区中的内容到本地仓库 -m 提交信息</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h4 id="忽略文件" tabindex="-1">忽略文件 <a class="header-anchor" href="#忽略文件" aria-label="Permalink to &quot;忽略文件&quot;">​</a></h4><p>有些时候我们不想把某些文件纳入版本控制中，比如数据库文件，临时文件，设计文件等。在主目录下建立&quot;.gitignore&quot;文件，此文件有如下规则：</p><ol><li>忽略文件中的空行或以井号（#）开始的行将会被忽略。</li><li>可以使用Linux通配符。例如：星号（*）代表任意多个字符，问号（？）代表一个字符，方括号（[abc]）代表可选字符范围，大括号（{string1,string2,...}）代表可选的字符串等。</li><li>如果名称的最前面有一个感叹号（!），表示例外规则，将不被忽略。</li><li>如果名称的最前面是一个路径分隔符（/），表示要忽略的文件在此目录下，而子目录中的文件不忽略。</li><li>如果名称的最后面是一个路径分隔符（/），表示要忽略的是此目录下该名称的子目录，而非文件（默认文件或目录都忽略）。</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#为注释</span></span>
<span class="line"><span>*.txt        #忽略所有 .txt结尾的文件,这样的话上传就不会被选中！</span></span>
<span class="line"><span>!lib.txt     #但lib.txt除外</span></span>
<span class="line"><span>/temp        #仅忽略项目根目录下的TODO文件,不包括其它目录temp</span></span>
<span class="line"><span>build/       #忽略build/目录下的所有文件</span></span>
<span class="line"><span>doc/*.txt    #会忽略 doc/notes.txt 但不包括 doc/server/arch.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="idea提交项目到gitee-码云" tabindex="-1">IDEA提交项目到Gitee(码云) <a class="header-anchor" href="#idea提交项目到gitee-码云" aria-label="Permalink to &quot;IDEA提交项目到Gitee(码云)&quot;">​</a></h2><p>首先需要在gitee上创建一个仓库.</p><p>IDEA提交项目到Gitee有两种操作,一种是图形化操作,一种是命令行操作</p><h3 id="图形化操作" tabindex="-1">图形化操作 <a class="header-anchor" href="#图形化操作" aria-label="Permalink to &quot;图形化操作&quot;">​</a></h3><h4 id="_1-创建本地git仓库" tabindex="-1">1.创建本地git仓库 <a class="header-anchor" href="#_1-创建本地git仓库" aria-label="Permalink to &quot;1.创建本地git仓库&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee1.png" alt="" loading="lazy"></p><p>​ <strong>默认选择当前项目</strong></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee2.png" alt="" loading="lazy"></p><p>​ <strong>完成之后,VCS会变成Git</strong></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee3.png" alt="" loading="lazy"></p><h4 id="_2-添加远程仓库地址" tabindex="-1">2.添加远程仓库地址 <a class="header-anchor" href="#_2-添加远程仓库地址" aria-label="Permalink to &quot;2.添加远程仓库地址&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee4.png" alt="" loading="lazy"></p><p><strong>复制在gitee上创建的仓库的地址</strong></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee5.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee6.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee7.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee8.png" alt="" loading="lazy"></p><h4 id="_3-将远端的文件pull到本地仓库" tabindex="-1">3.将远端的文件pull到本地仓库 <a class="header-anchor" href="#_3-将远端的文件pull到本地仓库" aria-label="Permalink to &quot;3.将远端的文件pull到本地仓库&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee9.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee10.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee11.png" alt="" loading="lazy"></p><h4 id="_4-刷新idea项目" tabindex="-1">4.刷新idea项目 <a class="header-anchor" href="#_4-刷新idea项目" aria-label="Permalink to &quot;4.刷新idea项目&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee12.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee13.png" alt="" loading="lazy"></p><h4 id="_5-将项目添加到暂存区" tabindex="-1">5.将项目添加到暂存区 <a class="header-anchor" href="#_5-将项目添加到暂存区" aria-label="Permalink to &quot;5.将项目添加到暂存区&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee14.png" alt="" loading="lazy"></p><h4 id="_6-将项目提交到本地仓库" tabindex="-1">6.将项目提交到本地仓库 <a class="header-anchor" href="#_6-将项目提交到本地仓库" aria-label="Permalink to &quot;6.将项目提交到本地仓库&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee15.png" alt="" loading="lazy"></p><p>​ <img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee16.png" alt="" loading="lazy"></p><h4 id="_7-将项目推送到远端" tabindex="-1">7.将项目推送到远端 <a class="header-anchor" href="#_7-将项目推送到远端" aria-label="Permalink to &quot;7.将项目推送到远端&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee17.png" alt="" loading="lazy"></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee18.png" alt="" loading="lazy"></p><h4 id="_8-刷新gitee仓库" tabindex="-1">8.刷新gitee仓库 <a class="header-anchor" href="#_8-刷新gitee仓库" aria-label="Permalink to &quot;8.刷新gitee仓库&quot;">​</a></h4><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-gitee19.png" alt="" loading="lazy"></p><p>然后就能看到推送到远端的文件了。</p><h3 id="命令行操作" tabindex="-1">命令行操作 <a class="header-anchor" href="#命令行操作" aria-label="Permalink to &quot;命令行操作&quot;">​</a></h3><p><strong>在idea底部选择Terminal</strong></p><p><img src="https://fanaidi.gitee.io/blogimgs/git/idea%E9%A1%B9%E7%9B%AE%E6%8F%90%E4%BA%A4%E5%88%B0gitee/idea-%E5%91%BD%E4%BB%A4%E8%A1%8C.png" alt="" loading="lazy"></p><p><strong>依次执行一下命令即可</strong></p><div class="language-Shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">Shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#初始化Git仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#和远端仓库建立连接</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> #远程仓库地址</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#将远程仓库的文件拉到本地</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#将项目的文件添加到暂存区</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#将添加到暂存区的文件提交到本地仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;提交的信息&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#将本地仓库推送到远端仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="git分支" tabindex="-1">GIT分支 <a class="header-anchor" href="#git分支" aria-label="Permalink to &quot;GIT分支&quot;">​</a></h2><p>分支在GIT中相对较难，分支就是科幻电影里面的平行宇宙，如果两个平行宇宙互不干扰，那对现在的你也没啥影响。不过，在某个时间点，两个平行宇宙合并了，我们就需要处理一些问题了！</p><h3 id="git分支中常用指令" tabindex="-1">git分支中常用指令： <a class="header-anchor" href="#git分支中常用指令" aria-label="Permalink to &quot;git分支中常用指令：&quot;">​</a></h3><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有本地分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有远程分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 新建一个分支，但依然停留在当前分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [branch-name]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 新建一个分支，并切换到该分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [branch]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 合并指定分支到当前分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [branch]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [branch-name]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除远程分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [branch-name]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [remote/branch]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>如果同一个文件在合并分支时都被修改了则会引起冲突：解决的办法是我们可以修改冲突文件后重新提交！选择要保留他的代码还是你的代码！</p><p>master主分支应该非常稳定，用来发布新版本，一般情况下不允许在上面工作，工作一般情况下在新建的dev分支上工作，工作完后，比如上要发布，或者说dev分支代码稳定后可以合并到主分支master上来。</p><p>详细信息请看:<a href="https://git-scm.com/book/zh/v2/Git-%E5%88%86%E6%94%AF-%E5%88%86%E6%94%AF%E7%AE%80%E4%BB%8B" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/Git-分支-分支简介</a></p>`,120)])])}const c=a(l,[["render",t]]);export{k as __pageData,c as default};
